  `name` VARCHAR(100) NOT NULL,
  `price` INT UNSIGNED NOT NULL COMMENT 'copper, from the guild bank',
  `team` TINYINT UNSIGNED NOT NULL COMMENT '0 both, 1 Alliance, 2 Horde',
  `limit_group` VARCHAR(32) NOT NULL COMMENT 'items sharing max_count; empty = the item alone',
