  `go_entry` INT UNSIGNED NOT NULL,
  `focus_entry` INT UNSIGNED NOT NULL COMMENT 'invisible spell focus placed with it',
  `npc_entry` INT UNSIGNED NOT NULL,
  `dest_map` INT NOT NULL COMMENT 'portals: -1 = none',
  `dest_x` FLOAT NOT NULL, `dest_y` FLOAT NOT NULL, `dest_z` FLOAT NOT NULL, `dest_o` FLOAT NOT NULL,
  `enabled` TINYINT UNSIGNED NOT NULL,
  `rise` FLOAT NOT NULL COMMENT 'yards the object stands above where it is placed',
  `guild_display` INT UNSIGNED NOT NULL COMMENT 'guild banners: this display id + the guild id is the one shown',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XorWoW: guild hall build mode catalogue';


